   105	public enum Xpb98Status {
   106	    PENDING {
   107	        @Override
   108	        public boolean canTransitionTo(Xpb98Status nextStatus) {
   109	            return nextStatus == SHIPPED || nextStatus == CANCELED;
   110	        }
   111	    },
   112	    SHIPPED {
   113	        @Override
   114	        public boolean canTransitionTo(Xpb98Status nextStatus) {
   115	            return nextStatus == IN_TRANSIT || nextStatus == RETURNED || nextStatus == CANCELED;
   116	        }
   117	    },
   118	    IN_TRANSIT {
   119	        @Override
   120	        public boolean canTransitionTo(Xpb98Status nextStatus) {
   121	            return nextStatus == OUT_FOR_DELIVERY || nextStatus == DELAYED || nextStatus == CANCELED
   122	                    || nextStatus == DELIVERED;
   123	        }
   124	    },
   125	    OUT_FOR_DELIVERY {
   126	        @Override
   127	        public boolean canTransitionTo(Xpb98Status nextStatus) {
   128	            return nextStatus == DELIVERED || nextStatus == FAILED_DELIVERY || nextStatus == CANCELED;
   129	        }
   130	    },
   131	    DELIVERED {
   132	        @Override
   133	        public boolean canTransitionTo(Xpb98Status nextStatus) {
   134	            return false;
   135	        }
   136	    },
   137	    RETURNED {
   138	        @Override
   139	        public boolean canTransitionTo(Xpb98Status nextStatus) {
   140	            return nextStatus == CANCELED;
   141	        }
   142	    },
   143	    CANCELED {
   144	        @Override
   145	        public boolean canTransitionTo(Xpb98Status nextStatus) {
   146	            return false;
   147	        }
   148	    },
   149	    DELAYED {
   150	        @Override
   151	        public boolean canTransitionTo(Xpb98Status nextStatus) {
   152	            return nextStatus == IN_TRANSIT || nextStatus == CANCELED;
   153	        }
   154	    },
   155	    FAILED_DELIVERY {
   156	        @Override
   157	        public boolean canTransitionTo(Xpb98Status nextStatus) {
   158	            return nextStatus == RETURNED || nextStatus == OUT_FOR_DELIVERY || nextStatus == CANCELED;
   159	        }
   160	    };
   161	
   162	    public abstract boolean canTransitionTo(Xpb98Status nextStatus);
   163	}
